 function carPositions(t,n,a,s=new Float32Array(t.length*3)){return t.forEach((c,l)=>{const{a:r,b:i}=n[c.lane],o=((c.start+a*c.speed/c.length)%1+1)%1,e=r[0]+(i[0]-r[0])*o,h=r[2]+(i[2]-r[2])*o;s[l*3]=e,s[l*3+1]=y(e,h)+1.2,s[l*3+2]=h}),s}export const CAR={length:4.6,width:1.9,height:1.45,lights:.8};export function carYaws(t,n){return t.map(({lane:a})=>{const{a:s,b:c}=n[a];return yawFor(c[0]-s[0],c[2]-s[2])})}export function carLightPositions(t,n,a,s=new Float32Array(t.length*3)){carPositions(t,n,a,s);const c=CAR.length/2+.2;return t.forEach((l,r)=>{const{a:i,b:o}=n[l.lane],e=Math.hypot(o[0]-i[0],o[2]-i[2]),h=l.red?-1:1;s[r*3]+=(o[0]-i[0])/e*c*h,s[r*3+1]+=CAR.lights-1.2,s[r*3+2]+=(o[2]-i[2])/e*c*h}),s}export function drift(t,n,a){const s=LIFE.wind*t.getTime()/1e3/a;return{clouds:[s%1,s*.35%1],ripple:[n*LIFE.ripple[0]%1,n*LIFE.ripple[1]%1]}}
